import html2canvas from"html2canvas";import jsPDF from"jspdf";let exportPDF=(e,i)=>{e=document.getElementById(e);let m=e.cloneNode(!0);m.querySelectorAll(".daily-card");m.style.height=e.scrollHeight+"px",m.style.zIndex=-1,document.body.appendChild(m),html2canvas(m,{allowTaint:!1,useCORS:!0}).then(e=>{var t=e.toDataURL("image/png"),a=(document.body.removeChild(m),new jsPDF("p","mm","a4")),d=e.width,e=e.height,l=(a.getImageProperties(t),a.internal.pageSize.getWidth()-20),o=a.internal.pageSize.getHeight(),n=e*l/d;let g=1;for(;o*g-n<0;)g,a.addImage(t,"png",10,(1-g)*o,l,n),a.addPage(),g++;g,a.addImage(t,"png",10,(1-g)*o,l,n),a.save(i)})};export{exportPDF};